import { auth } from "./auth"

export default auth((req) => {
  const isLoggedIn = !!req.auth
  const isManagerRoute = req.nextUrl.pathname.startsWith('/manager-dash')
  const isPrepRoute = req.nextUrl.pathname.startsWith('/prep-dash')

  if (!isLoggedIn && (isManagerRoute || isPrepRoute)) {
    return Response.redirect(new URL('/login', req.nextUrl))
  }
})

export const config = {
  matcher: ['/manager-dash/:path*', '/prep-dash/:path*']
}